List<ExerciseModel> _applyEquipmentMetadataAudit(
  List<ExerciseModel> exercises,
) => exercises
    .map(
      (exercise) => _equipmentMetadataOverrides[exercise.id] == null
          ? exercise
          : exercise.copyWith(
              equipment: _equipmentMetadataOverrides[exercise.id],
            ),
    )
    .toList();

